sysevent_script_action.script:
function getPCEAsyncJobStatus() {

	var illumioPollAsyncJobStatus = new IllumioPollAsyncJobStatus(
		current.job_location, 
		current.retry_interval, 
		current.sys_id,
		current.primary_key_to_map,
		current.result_table_name,
		current.keys_to_map,
		current.retry_count,
		current.illumio_job_id,
		current.job_identifier,
		// For the poll line's elapsed figure. Taken from the record this action already holds,
		// so it costs nothing -- IllumioPollAsyncJobStatus would otherwise have to re-query the
		// async job once per poll to learn when it started.
		current.sys_created_on
	);
	illumioPollAsyncJobStatus.execute();
}
getPCEAsyncJobStatus();
